+static void count_and_rearrange(uint32_t* a, size_t n, int digit, uint32_t* tmp, uint32_t* counts) {
+    // Clear counts
+    for (int i = 0; i < 256; ++i) counts[i] = 0;
+    // Count occurrences of each digit
+    for (size_t i = 0; i < n; ++i) {
+        uint8_t d = (a[i] >> (digit * 8)) & 0xFF;
+        counts[d]++;
