+    // Convert to cumulative counts
+    for (int i = 1; i < 256; ++i) counts[i] += counts[i-1];
+    // Rearrange elements into tmp based on digit
+    for (size_t i = n; i > 0; --i) {
+        uint8_t d = (a[i-1] >> (digit * 8)) & 0xFF;
+        tmp[--counts[d]] = a[i-1];
+    }
+    // Copy back to a
+    std::memcpy(a, tmp, n * sizeof(uint32_t));
